CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,phone text UNIQUE,password_hash text NOT NULL,role text NOT NULL CHECK(role IN('PASSENGER','DRIVER','ADMIN','COMPANY_USER')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE passengers(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,first_name text NOT NULL,last_name text NOT NULL);
CREATE TABLE companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),legal_name text NOT NULL,siren text UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE drivers(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,revtc_number text UNIQUE,professional_card_number text UNIQUE,professional_card_expires_at date,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','ACTIVE','SUSPENDED','INACTIVE')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vehicles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),driver_id uuid NOT NULL REFERENCES drivers(user_id),registration_number text NOT NULL UNIQUE,make text,model text,energy_type text,seats smallint NOT NULL DEFAULT 4 CHECK(seats>0),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE driver_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),driver_id uuid NOT NULL REFERENCES drivers(user_id) ON DELETE CASCADE,document_type text NOT NULL,document_number text,expires_at date,verified_at timestamptz,status text NOT NULL DEFAULT 'PENDING');
CREATE TABLE vehicle_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vehicle_id uuid NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,document_type text NOT NULL,expires_at date,verified_at timestamptz,status text NOT NULL DEFAULT 'PENDING');
